css:
.d-lt-stage{--lx:50%;--ly:0%;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;width:100%;max-width:340px;height:180px;border:1px solid var(--line);border-radius:10px;background:var(--bg);overflow:hidden}
.d-lt-card{position:relative;width:220px;padding:16px 16px 18px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden;box-shadow:0 1px 0 var(--line)}
.d-lt-card:before{content:"";position:absolute;left:0;top:0;width:100%;height:100%;background:radial-gradient(120px 120px at var(--lx,50%) var(--ly,0%),color-mix(in srgb,var(--marker-hi) 55%,transparent),transparent 62%);opacity:0;transition:opacity 220ms var(--ease-print);pointer-events:none}
.d-lt-card:after{content:"";position:absolute;left:0;top:0;width:100%;height:100%;background:radial-gradient(60px 60px at var(--lx,50%) var(--ly,0%),color-mix(in srgb,var(--paper) 80%,transparent),transparent 70%);opacity:0;transition:opacity 220ms var(--ease-print);pointer-events:none}
.d-lt-stage.d-lt-on .d-lt-card:before{opacity:.18}
.d-lt-stage.d-lt-on .d-lt-card:after{opacity:.5}
.d-lt-k{display:block;font-family:var(--font-mono);font-size:9px;letter-spacing:.1em;color:var(--faint)}
.d-lt-card b{display:block;margin-top:2px;font-size:17px;font-weight:650;letter-spacing:-.01em}
.d-lt-meta{display:block;margin-top:2px;font-size:11px;color:var(--muted)}
.d-lt-note{position:absolute;bottom:8px;margin:0;font-size:10px;color:var(--faint)}
@media (prefers-reduced-motion:reduce){.d-lt-card:before,.d-lt-card:after{transition:none}}

init:
root => {
  const stage = root.querySelector('.d-lt-stage');
  const card = stage && stage.querySelector('.d-lt-card');
  if (!stage || !card) return;
  stage.addEventListener('pointermove', e => {
    const r = card.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
    const y = Math.max(0, Math.min(1, (e.clientY - r.top) / r.height));
    card.style.setProperty('--lx', (x * 100).toFixed(1) + '%');
    card.style.setProperty('--ly', (y * 100).toFixed(1) + '%');
    stage.classList.add('d-lt-on');
  });
  stage.addEventListener('pointerleave', () => stage.classList.remove('d-lt-on'));
}
